import com.hbm.ore.RawOreContent;
import com.hbm.recipe.LegacyOreIngredient;
import com.hbm.recipe.generic.*;
import com.hbm.registry.HbmOreDictionary;
import com.mojang.logging.LogUtils;
import com.mojang.serialization.JsonOps;
import java.nio.file.*;
import java.util.*;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.item.crafting.*;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.fml.loading.FMLPaths;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.OnDatapackSyncEvent;
import net.neoforged.neoforge.event.server.ServerAboutToStartEvent;
/** Native actual source recipes and old hbmCrystallizer.json grammar, without fabricated missing stage items. */
public final class CrystallizerRecipeConfig {
 private static final Map<RecipeManager,Map<ResourceLocation,RecipeHolder<?>>> INSTALLED=new WeakHashMap<>();private static final Map<String,String> ALIASES=new LinkedHashMap<>();
 public static void register(){try(var stream=CrystallizerRecipeConfig.class.getResourceAsStream("/hbm/crystallizer-item-aliases.json")){if(stream!=null)JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().entrySet().forEach(e->ALIASES.put(e.getKey(),e.getValue().getAsString()));}catch(Exception error){throw new IllegalStateException(error);}NeoForge.EVENT_BUS.addListener((ServerAboutToStartEvent e)->install(e.getServer()));NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,(OnDatapackSyncEvent e)->{var server=e.getPlayerList().getServer();if(e.getPlayer()==null||!INSTALLED.containsKey(server.getRecipeManager()))install(server);});}
 public static List<CrystallizerRecipe> recipes(RecipeManager manager){return manager.getAllRecipesFor(CrystallizerContent.TYPE.get()).stream().map(RecipeHolder::value).sorted(Comparator.comparingInt(r->r.data().order())).toList();}
 public static CrystallizerRecipe find(RecipeManager manager,ItemStack input,HbmFluidType type){if(input.isEmpty())return null;var matching=recipes(manager).stream().filter(r->(type==null||r.inputFluids().getFirst().type==type)&&r.inputItems().getFirst().matchesProcessing(input,true)).toList();for(var kind:List.of("item","dict","wildcard")){if(kind.equals("dict")){for(String tag:HbmOreDictionary.tags(RawOreContent.processingStack(input)))for(int i=matching.size()-1;i>=0;i--){var r=matching.get(i);if(r.keyKind().equals(kind)&&r.sourceKey().equals(tag))return r;}}else for(int i=matching.size()-1;i>=0;i--)if(matching.get(i).keyKind().equals(kind))return matching.get(i);}return null;}
 /** Source CrystallizerRecipes.getAmount: exact, ordered dictionary, wildcard; last registered quantity across all fluids. */
 public static int getAmount(RecipeManager manager,ItemStack input){var recipe=find(manager,input,null);return recipe==null?0:recipe.inputItems().getFirst().count();}
    public static void reload(MinecraftServer server) { install(server); }
 private static void install(MinecraftServer server){var manager=server.getRecipeManager();var previous=INSTALLED.getOrDefault(manager,Map.of());var merged=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();for(var h:manager.getOrderedRecipes())if(previous.get(h.id())!=h)merged.put(h.id(),h);var added=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();Path directory=FMLPaths.CONFIGDIR.get().resolve("hbmRecipes"),active=directory.resolve("hbmCrystallizer.json");try{Files.createDirectories(directory);if(Files.isRegularFile(active)){merged.values().removeIf(h->h.value().getType()==CrystallizerContent.TYPE.get());JsonObject root;try(var reader=Files.newBufferedReader(active)){root=JsonParser.parseReader(reader).getAsJsonObject();}int i=0;for(var value:root.getAsJsonArray("recipes")){try{var recipe=legacy(value.getAsJsonObject(),server.registryAccess(),i);var id=ResourceLocation.parse("hbm:crystallizer/config/"+i);added.put(id,new RecipeHolder<>(id,recipe));}catch(Exception error){LogUtils.getLogger().warn("Unbound actual crystallizer custom row {}",i,error);}i++;}}else{compat(added);var defaults=new java.util.ArrayList<>(recipes(manager));for(var holder:added.values())defaults.add((CrystallizerRecipe)holder.value());template(directory.resolve("_hbmCrystallizer.json"),defaults);}}catch(Exception error){LogUtils.getLogger().error("Cannot load source crystallizer replacement recipes",error);}added.forEach(merged::put);if(!added.isEmpty()||!previous.isEmpty()||Files.isRegularFile(active))manager.replaceRecipes(merged.values());INSTALLED.put(manager,added);}
 private static void compat(Map<ResourceLocation,RecipeHolder<?>> added){var certus=HbmOreDictionary.items("hbm:legacy_ore_dict/crystalcertusquartz").findFirst().orElse(ItemStack.EMPTY);if(!certus.isEmpty())compatRecipe(added,"certus","oreCertusQuartz",certus.copyWithCount(12),"PEROXIDE",500,600);if(HbmOreDictionary.items("hbm:legacy_ore_dict/dustwhitephosphorus").findAny().isPresent())compatRecipe(added,"white_phosphorus","dustWhitePhosphorus",MaterialDistributionConfig.legacyStack("hbm:ingot_phosphorus",0),"AROMATICS",50,100);if(HbmOreDictionary.items("hbm:legacy_ore_dict/dustcinnabar").findAny().isPresent())compatRecipe(added,"cinnabar","dustCinnabar",MaterialDistributionConfig.legacyStack("hbm:cinnebar",0),"PEROXIDE",50,100);}
 private static void compatRecipe(Map<ResourceLocation,RecipeHolder<?>> added,String id,String raw,ItemStack output,String fluid,int amount,int time){if(output.isEmpty())return;String key=HbmOreDictionary.registerName(raw);var ingredient=new GenericIngredient(new LegacyOreIngredient(ResourceLocation.parse(key)).toVanilla(),1);var data=new GenericRecipeData("crystallizer.compat."+id,time,1000,List.of(ingredient),List.of(new FluidStack(HbmFluids.fromName(fluid),amount)),List.of(new GenericOutput(output)),List.of(),List.of(),"",ItemStack.EMPTY,false,"",100000+added.size());var location=ResourceLocation.parse("hbm:crystallizer/compat/"+id);added.put(location,new RecipeHolder<>(location,new CrystallizerRecipe(data,0,"dict",key)));}
 private static ItemStack stack(JsonArray spec)throws Exception{String name=spec.get(0).getAsString();int metadata=spec.size()>2?spec.get(2).getAsInt():0;String actual=ALIASES.getOrDefault(name,name);if(actual.equals("minecraft:dye")&&(metadata==4||metadata==15)){actual=metadata==4?"minecraft:lapis_lazuli":"minecraft:bone_meal";metadata=0;}var stack=MaterialDistributionConfig.legacyStack(actual,metadata);if(stack.isEmpty())throw new IllegalArgumentException("Unregistered original item "+name);stack.setCount(spec.size()>1?spec.get(1).getAsInt():1);if(spec.size()>3)stack.set(DataComponents.CUSTOM_DATA,CustomData.of(TagParser.parseTag(spec.get(3).getAsString())));return stack;}
 private static CrystallizerRecipe legacy(JsonObject row,HolderLookup.Provider lookup,int order)throws Exception{var in=row.getAsJsonArray("input");String kind=in.get(0).getAsString(),sourceKey;int count=in.size()>2?in.get(2).getAsInt():1,meta=in.size()>3?in.get(3).getAsInt():0;Ingredient ingredient;if(kind.equals("dict")){sourceKey=HbmOreDictionary.registerName(in.get(1).getAsString());ingredient=new LegacyOreIngredient(ResourceLocation.parse(sourceKey)).toVanilla();}else{JsonArray spec=new JsonArray();spec.add(in.get(1));spec.add(1);spec.add(kind.equals("nbt")?0:meta);var example=stack(spec);sourceKey=in.get(1).getAsString();ingredient=new CentrifugeNbtIngredient(example,kind.equals("nbt")&&in.size()>4?TagParser.parseTag(in.get(4).getAsString()):new CompoundTag()).toVanilla();kind=meta==32767?"wildcard":"item";}var out=stack(row.getAsJsonArray("output"));var fluid=row.getAsJsonArray("fluid");var acid=new FluidStack(HbmFluids.fromName(fluid.get(0).getAsString()),fluid.get(1).getAsInt(),0);var output=new GenericOutput(List.of(new GenericOutput.Chance(out,1,0)),false);var data=new GenericRecipeData("crystallizer.config."+order,row.get("duration").getAsInt(),1000,List.of(new GenericIngredient(ingredient,count)),List.of(acid),List.of(output),List.of(),List.of(),"",ItemStack.EMPTY,false,"",order);return new CrystallizerRecipe(data,row.has("productivity")?row.get("productivity").getAsFloat():0,kind,sourceKey);}
 private static JsonArray array(Object... values){var a=new JsonArray();for(var value:values)if(value instanceof Number n)a.add(n);else a.add(value.toString());return a;}
 private static JsonArray jsonStack(ItemStack stack){var a=array(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).toString(),stack.getCount(),stack.getOrDefault(HbmHazards.LEGACY_METADATA.get(),stack.getDamageValue()));if(stack.has(DataComponents.CUSTOM_DATA))a.add(stack.get(DataComponents.CUSTOM_DATA).copyTag().toString());return a;}
 private static void template(Path path,List<CrystallizerRecipe> recipes)throws Exception{var root=new JsonObject();var rows=new JsonArray();for(var recipe:recipes){var ing=recipe.inputItems().getFirst();var custom=ing.ingredient().getCustomIngredient();var input=custom instanceof LegacyOreIngredient ore?array("dict",HbmOreDictionary.allNames().stream().filter(n->("hbm:legacy_ore_dict/"+n.toLowerCase(Locale.ROOT)).equals(ore.tag().toString())).findFirst().orElse(ore.tag().getPath().substring("legacy_ore_dict/".length())),ing.count()):null;if(input==null){var examples=ing.ingredient().getItems();if(examples.length==0)continue;var s=examples[0];input=array("item",net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(s.getItem()).toString(),ing.count(),s.getOrDefault(HbmHazards.LEGACY_METADATA.get(),s.getDamageValue()));}var row=new JsonObject();row.add("input",input);row.add("output",jsonStack(recipe.getResultItem(null)));var fluid=recipe.inputFluids().getFirst();row.add("fluid",array(fluid.type.getName(),fluid.fill));row.addProperty("duration",recipe.duration());row.addProperty("productivity",recipe.productivity());rows.add(row);}root.add("recipes",rows);Files.writeString(path,new GsonBuilder().setPrettyPrinting().create().toJson(root)+"\n");}
 private CrystallizerRecipeConfig(){}
}
